document.addEventListener("DOMContentLoaded",(function(){var e=document.querySelector("#chatbot-form"),t=document.querySelector("#chatbot-question"),n=document.querySelector("#chatbot-response");e&&t&&n&&e.addEventListener("submit",(function(e){e.preventDefault();var o=t.value.trim();o?(n.textContent="Recherche de réponse...",fetch("index.php?url=chatbot-api",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({question:o})}).then((function(e){return e.json()})).then((function(e){e.success?n.textContent=e.answer:n.textContent=e.message||"Impossible de récupérer la réponse."})).catch((function(){n.textContent="Erreur lors de la connexion au chatbot. Réessayez plus tard."}))):n.textContent="Veuillez saisir une question."}))}));